mapper.select:
SELECT COUNT(1)
FROM public.skill_effects
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND effect_key = #{effectKey}

mapper.insert:
INSERT INTO public.skill_effects (
    game_id, skill_key, effect_key, name, description, sort_order, results, lifecycle
) VALUES (
    #{gameId}, #{skillKey}, #{effectKey}, #{name}, #{description}, #{sortOrder},
    CAST(#{results} AS jsonb), CAST(#{lifecycle,jdbcType=VARCHAR} AS jsonb)
)

mapper.select:
SELECT formula_key
FROM public.skill_formulas
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND formula_key IN

    #{key}

ORDER BY formula_key
FOR UPDATE

SELECT damage_type_key AS ref_key, status FROM public.damage_types WHERE game_id = #{gameId} AND damage_type_key IN
#{key}
ORDER BY damage_type_key FOR UPDATE

SELECT attribute_key AS ref_key, status FROM public.attributes WHERE game_id = #{gameId} AND attribute_key IN
#{key}
ORDER BY attribute_key FOR UPDATE

SELECT skill_key AS ref_key, status FROM public.skills WHERE game_id = #{gameId} AND skill_key IN
#{key}
ORDER BY skill_key FOR UPDATE

SELECT skill_category_key AS ref_key, status FROM public.skill_categories WHERE game_id = #{gameId} AND skill_category_key IN
#{key}
ORDER BY skill_category_key FOR UPDATE

SELECT status_key AS ref_key, status, status_kind FROM public.statuses WHERE game_id = #{gameId} AND status_key IN
#{key}
ORDER BY status_key FOR UPDATE

SELECT modifier_zone_key, domain, status FROM public.modifier_zones WHERE game_id = #{gameId} AND modifier_zone_key IN
#{key}
ORDER BY modifier_zone_key FOR UPDATE

SELECT DISTINCT f.formula_key FROM public.skill_formulas f CROSS JOIN LATERAL jsonb_path_query(f.expression, '$.**.parameterKey') n(parameter_key) JOIN public.skill_parameters p ON p.game_id = f.game_id AND p.skill_key = f.skill_key AND p.parameter_key = n.parameter_key #>> '{}' WHERE f.game_id = #{gameId} AND f.skill_key = #{skillKey} AND f.formula_key IN
#{key}
AND p.value_mode = 'RUNTIME_INPUT' ORDER BY f.formula_key

SELECT COUNT(1)
FROM public.skill_effects e
CROSS JOIN LATERAL jsonb_array_elements(e.results) r
WHERE e.game_id = #{gameId} AND e.skill_key = #{skillKey}
  AND r ->> 'resultType' = 'LIFECYCLE_OPERATION'
  AND r #>> '{detail,targetEffectKey}' = #{targetEffectKey}

SELECT effect_key
FROM public.skill_effects
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND effect_key IN

    #{key}

ORDER BY effect_key
FOR UPDATE

SELECT game_id, skill_key, effect_key, lifecycle ->> 'durationValue' AS duration_value, lifecycle ->> 'maxStacksValue' AS max_stacks_value, lifecycle ->> 'applicationStacksValue' AS application_stacks_value, lifecycle ->> 'instanceScope' AS instance_scope, lifecycle ->> 'reapplicationStackMode' AS reapplication_stack_mode, lifecycle ->> 'reapplicationDurationMode' AS reapplication_duration_mode, lifecycle ->> 'expiryMode' AS expiry_mode, lifecycle ->> 'periodicIntervalValue' AS periodic_interval_value, lifecycle ->> 'firstPeriodicExecution' AS first_periodic_execution FROM public.skill_effects WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND lifecycle IS NOT NULL AND effect_key IN
#{key}
ORDER BY effect_key FOR UPDATE
